// Opt-in laboratory integration. Requires a real compiled Rust verifier and
// public fixtures generated by the pinned snapshot_monitor Rust test.
// This is not a native DOM consensus or production privacy test.
import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs/promises';
import path from 'node:path';
import {createServer} from 'node:http';
import {once} from 'node:events';
import {snapshotReader} from '../../scripts/candidate-monitor.mjs';

const binary = process.env.USDOM_RUST_VERIFIER;
const fixture = process.env.USDOM_PUBLIC_FIXTURE;
assert(binary && path.isAbsolute(binary), 'USDOM_RUST_VERIFIER must identify the compiled verifier');
assert(fixture && path.isAbsolute(fixture), 'USDOM_PUBLIC_FIXTURE must identify generated public fixtures');
const expected = JSON.parse(await fs.readFile(path.join(fixture, 'expected-view.json'), 'utf8'));

async function source(t, name, networkId = expected.network) {
  const body = await fs.readFile(path.join(fixture, name));
  const server = createServer((request, response) => {
    if (request.url !== '/snapshot') { response.writeHead(404); response.end(); return; }
    response.writeHead(200, {'content-type':'application/json'}); response.end(body);
  });
  server.listen(0, '127.0.0.1'); await once(server, 'listening');
  t.after(() => new Promise(resolve => {server.close(resolve); server.closeAllConnections();}));
  return snapshotReader({url:`http://127.0.0.1:${server.address().port}`, binary,
    networkDirectory:path.join(fixture, 'public'), networkId, timeoutMs:30_000});
}

test('real Rust replay reaches the Node adapter without losing integer precision', async t => {
  const reader = await source(t, 'valid-snapshot.json');
  const actual = await reader.read();
  assert.deepEqual(actual, expected);
  assert.equal(actual.records[0].amount, '9007199254740993');
  assert.equal(actual.ordering, 'single-sequencer-experimental');
});

test('a signed snapshot with an invalid embedded proof is rejected by the real adapter', async t => {
  const reader = await source(t, 'invalid-proof-snapshot.json');
  await assert.rejects(reader.read());
});

test('a valid snapshot cannot override the locally pinned network identity', async t => {
  const reader = await source(t, 'valid-snapshot.json', '0x'+'01'.repeat(32));
  await assert.rejects(reader.read());
});
